public protocol ZreeSessionProtocol: AnyObject, Sendable {
    
    /**
     * Fill creation times for notes the filesystem could not date (Android),
     * typically from `GitRepo.firstAddedTimes()`.
     */
    func applyCreatedTimes(times: [CreatedAt])  -> UInt32
    
    /**
     * Markdown token stream for a note on disk.
     */
    func blocks(id: String) throws  -> [Block]
    
    /**
     * Markdown token stream for live editor text (preview pane).
     */
    func blocksOf(text: String)  -> [Block]
    
    func create(title: String?, body: String) throws  -> NoteMeta
    
    /**
     * Image sources referenced by a note, for the native image loader.
     */
    func imageSources(id: String) throws  -> [String]
    
    func inline(text: String)  -> [Inline]
    
    func list() throws  -> [NoteMeta]
    
    /**
     * The whole list in the requested order (used when nothing is being searched).
     */
    func listRows(order: SortOrder)  -> [Hit]
    
    func read(id: String) throws  -> String
    
    /**
     * Force a reindex (after a git pull, or when files changed outside the app).
     */
    func reindex() throws 
    
    func rename(id: String, title: String) throws  -> NoteMeta
    
    /**
     * Absolute path of a vault-relative resource (images etc.).
     */
    func resolveAsset(id: String, src: String) throws  -> String
    
    /**
     * Resolve a Markdown link to a note id in this vault (None if external/missing).
     */
    func resolveLink(id: String, href: String)  -> String?
    
    func root()  -> String
    
    func search(query: String, tags: [String], limit: UInt32)  -> [Hit]
    
    /**
     * Note candidates for the given prefix (no `[`), newest first.
     */
    func suggestNotes(prefix: String, limit: UInt32)  -> [NoteSuggestion]
    
    /**
     * Tag candidates for the given prefix (no `#`), e.g. "お客" -> "お客様打合せ".
     */
    func suggestTags(prefix: String, limit: UInt32)  -> [String]
    
    func tags()  -> [TagCount]
    
    func trash(id: String) throws  -> String
    
    /**
     * Overwrite a note. Rejected when the file changed on disk since `seen_mtime_ms`.
     */
    func write(id: String, body: String, seenMtimeMs: Int64) throws  -> NoteMeta
    
}
