public enum Block: Equatable, Hashable {
    
    case blank
    case heading(level: UInt8, text: String, line: UInt32
    )
    case listItem(indent: UInt8, ordered: Bool, checked: Bool?, text: String, line: UInt32
    )
    case quote(text: String, line: UInt32
    )
    case image(src: String, alt: String, line: UInt32
    )
    case code(lang: String, text: String, line: UInt32
    )
    /**
     * `---`, `***` or `___` on a line of its own.
     */
    case rule(line: UInt32
    )
    case paragraph(text: String, line: UInt32
    )





}

#if compiler(>=6)
extension Block: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlock: FfiConverterRustBuffer {
    typealias SwiftType = Block

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Block {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .blank
        
        case 2: return .heading(level: try FfiConverterUInt8.read(from: &buf), text: try FfiConverterString.read(from: &buf), line: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 3: return .listItem(indent: try FfiConverterUInt8.read(from: &buf), ordered: try FfiConverterBool.read(from: &buf), checked: try FfiConverterOptionBool.read(from: &buf), text: try FfiConverterString.read(from: &buf), line: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 4: return .quote(text: try FfiConverterString.read(from: &buf), line: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 5: return .image(src: try FfiConverterString.read(from: &buf), alt: try FfiConverterString.read(from: &buf), line: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 6: return .code(lang: try FfiConverterString.read(from: &buf), text: try FfiConverterString.read(from: &buf), line: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 7: return .rule(line: try FfiConverterUInt32.read(from: &buf)
        )
        
        case 8: return .paragraph(text: try FfiConverterString.read(from: &buf), line: try FfiConverterUInt32.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Block, into buf: inout [UInt8]) {
        switch value {
        
        
        case .blank:
            writeInt(&buf, Int32(1))
        
        
        case let .heading(level,text,line):
            writeInt(&buf, Int32(2))
            FfiConverterUInt8.write(level, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterUInt32.write(line, into: &buf)
            
        
        case let .listItem(indent,ordered,checked,text,line):
            writeInt(&buf, Int32(3))
            FfiConverterUInt8.write(indent, into: &buf)
            FfiConverterBool.write(ordered, into: &buf)
            FfiConverterOptionBool.write(checked, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterUInt32.write(line, into: &buf)
            
        
        case let .quote(text,line):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(text, into: &buf)
            FfiConverterUInt32.write(line, into: &buf)
            
        
        case let .image(src,alt,line):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(src, into: &buf)
            FfiConverterString.write(alt, into: &buf)
            FfiConverterUInt32.write(line, into: &buf)
            
        
        case let .code(lang,text,line):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(lang, into: &buf)
            FfiConverterString.write(text, into: &buf)
            FfiConverterUInt32.write(line, into: &buf)
            
        
        case let .rule(line):
            writeInt(&buf, Int32(7))
            FfiConverterUInt32.write(line, into: &buf)
            
        
        case let .paragraph(text,line):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(text, into: &buf)
            FfiConverterUInt32.write(line, into: &buf)
            
        }
    }
}


